package com.bank.validate;

import java.util.logging.Logger;

public class PalindromeFinder {

    private static final Logger log = Logger.getLogger(PalindromeFinder.class.getName());

    public String longestPalindrome(String s) {
        if (s == null || s.isEmpty()) return "";
        int start = 0, end = 0;
        for (int i = 0; i < s.length(); i++) {
            int odd = expand(s, i, i);                 // odd-length center
            int even = expand(s, i, i + 1);            // even-length center
            int len = Math.max(odd, even);
            if (len > end - start + 1) {
                start = i - (len - 1) / 2;             // recompute bounds from length
                end = i + len / 2;
            }
        }
        String result = s.substring(start, end + 1);
        log.info(() -> "Longest palindrome = " + result);
        return result;
    }

    private int expand(String s, int l, int r) {
        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
            l--; r++;                                  // grow while both sides match
        }
        return r - l - 1;                              // overshoots by one each side
    }
}
