package com.bank.validate;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PalindromeSubstringDemo {

    private static final Logger log = Logger.getLogger(PalindromeSubstringDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Palindrome Finder (Longest Substring)");
        PalindromeFinder finder = new PalindromeFinder();
        log.info("babad → " + finder.longestPalindrome("babad")); // bab (or aba)
        log.info("cbbd → " + finder.longestPalindrome("cbbd"));    // bb
    }
}
